import {createTokenizer} from '../shared/index.js'
import MiniSearch from 'minisearch'
import pMap from 'p-map'
import sanitizeHTML from 'sanitize-html'
import {colors, getDirname, logger, path} from 'vuepress/utils'
import {addViteOptimizeDepsInclude, getFullLocaleConfig} from '@vuepress/helper'
export * from '../shared/index.js'

const SEARCH_INDEX_DIR = 'internal/minisearchIndex/'

const MAX_SEARCHABLE_TEXT_LENGTH = 8e3

const SEARCH_INDEX_SHARD_SIZE = 5e4

const indexByLocales = /* @__PURE__ */ new Map()

const indexCache = /* @__PURE__ */ new Map()

const writtenIndexFingerprints = /* @__PURE__ */ new Map()

function getIndexByLocale(locale, lang, options) {
  let index = indexByLocales.get(locale)
  if (!index) {
    index = new MiniSearch({
      fields: ['title', 'titles', 'text'],
      storeFields: ['title', 'titles'],
      tokenize: createTokenizer(lang),
      ...options.miniSearch?.options,
    })
    indexByLocales.set(locale, index)
  }
  return index
}

function getIndexCache(filepath) {
  let index = indexCache.get(filepath)
  if (!index) {
    index = []
    indexCache.set(filepath, index)
  }
  return index
}

async function prepareSearchIndexPlaceholder(app) {
  await app.writeTemp(`${SEARCH_INDEX_DIR}index.js`, 'export const searchIndex = {}')
}

async function prepareSearchIndex({app, isSearchable, searchOptions}) {
  const start = performance.now()
  indexByLocales.clear()
  indexCache.clear()
  writtenIndexFingerprints.clear()
  await pMap(app.pages, (p) => indexFile(p, searchOptions, isSearchable), {concurrency: 64})
  await writeTemp(app)
  if (app.env.isBuild) {
    indexByLocales.clear()
    indexCache.clear()
  }
  if (app.env.isDebug)
    logger.info(
      `\n[${colors.green('@vuepress-plume/plugin-search')}] prepare search time spent: ${(performance.now() - start).toFixed(2)}ms`,
    )
}

let indexTaskQueue = Promise.resolve()
function runExclusive(task) {
  const result = indexTaskQueue.then(task)
  indexTaskQueue = result.then(
    () => {},
    () => {},
  )
  return result
}

function prepareSearchIndexInBackground(options) {
  runExclusive(() => prepareSearchIndex(options)).catch((error) => {
    logger.error(
      `${colors.green('[@vuepress-plume/plugin-search]')} failed to prepare search index:`,
      error,
    )
  })
}

async function onSearchIndexUpdated(app, {page, isSearchable, searchOptions}) {
  if (isSearchable && !isSearchable(page)) return
  await runExclusive(async () => {
    await indexFile(page, searchOptions, isSearchable)
    await writeTemp(app)
  })
}

async function onSearchIndexRemoved(app, {page, isSearchable, searchOptions}) {
  if (isSearchable && !isSearchable(page)) return
  const cacheKey = page.filePathRelative
  if (!cacheKey) return
  await runExclusive(async () => {
    const index = getIndexByLocale(page.pathLocale, page.lang, searchOptions)
    const cache = indexCache.get(cacheKey)
    if (cache?.length) index.removeAll(cache)
    indexCache.delete(cacheKey)
    await writeTemp(app)
  })
}

function splitSearchIndex(serialized, shardSize = SEARCH_INDEX_SHARD_SIZE) {
  const {index} = serialized
  if (shardSize <= 0 || index.length <= shardSize)
    return {
      meta: serialized,
      shards: [],
    }
  const shards = []
  for (let i = 0; i < index.length; i += shardSize) shards.push(index.slice(i, i + shardSize))
  return {
    meta: {
      ...serialized,
      index: [],
    },
    shards,
  }
}

function buildIndexFiles(localeName, serialized, shardSize = SEARCH_INDEX_SHARD_SIZE) {
  const {meta, shards} = splitSearchIndex(serialized, shardSize)
  const files = {}
  shards.forEach((entries, i) => {
    files[`searchBox-${localeName}-${i}.js`] =
      `export default ${JSON.stringify(JSON.stringify(entries))}`
  })
  const shardImports = shards.length
    ? `\nexport const shards = [${shards.map((_, i) => `() => import('@${SEARCH_INDEX_DIR}searchBox-${localeName}-${i}.js')`).join(', ')}]`
    : ''
  files[`searchBox-${localeName}.js`] =
    `export default ${JSON.stringify(JSON.stringify(meta))}${shardImports}`
  return files
}

async function writeTemp(app) {
  const records = []
  const promises = []
  const writeIfChanged = (filename, content) => {
    const filePath = `${SEARCH_INDEX_DIR}${filename}`
    if (writtenIndexFingerprints.get(filePath) === content) return
    promises.push(
      app.writeTemp(filePath, content).then(() => {
        writtenIndexFingerprints.set(filePath, content)
      }),
    )
  }
  for (const [locale, localeIndex] of indexByLocales) {
    const localeName = locale.replace(/^\/|\/$/g, '').replace(/\//g, '_') || 'default'
    records.push(
      `${JSON.stringify(locale)}: () => import('@${SEARCH_INDEX_DIR}searchBox-${localeName}.js')`,
    )
    const files = buildIndexFiles(localeName, localeIndex.toJSON())
    for (const [filename, content] of Object.entries(files)) writeIfChanged(filename, content)
  }
  writeIfChanged(
    'index.js',
    `export const searchIndex = {${records.join(',')}}${app.env.isDev ? `\n${genHmrCode('searchIndex')}` : ''}`,
  )
  await Promise.all(promises)
}

async function indexFile(page, options, isSearchable) {
  if (!page.filePath || page.frontmatter?.search === false) return
  if (isSearchable && !isSearchable(page)) return
  const fileId = page.path
  const index = getIndexByLocale(page.pathLocale, page.lang, options)
  const cache = getIndexCache(page.filePathRelative ?? fileId)
  try {
    if (cache.length) index.removeAll(cache)
  } catch (error) {
    logger.error(
      `${colors.green('[@vuepress-plume/plugin-search]')} failed to remove stale index entries:`,
      error,
    )
  }
  cache.length = 0
  for (const item of createPageSectionItems(page))
    if (index.has(item.id)) {
      if (item.id !== fileId)
        logger.error(
          `${colors.green('[@vuepress-plume/plugin-search]')} duplicate heading anchor : ${colors.cyan([...item.titles, item.title].join(' >> '))} \n at ${colors.cyan(fileId)}`,
        )
      else
        logger.error(
          `${colors.green('[@vuepress-plume/plugin-search]')} duplicate page permalink : ${colors.cyan(fileId)}`,
        )
    } else {
      index.add(item)
      cache.push(item)
    }
}

function* createPageSectionItems(page) {
  const html = `<h1><a href="#"><span>${page.frontmatter.title || page.title || page.filePathRelative || ''}</span></a></h1>\n${page.contentRendered}`
  const fileId = page.path
  for (const section of splitPageIntoSections(html)) {
    const {anchor, text, titles} = section

    if (!text && !titles.length) continue
    yield {
      id: anchor ? `${fileId}#${anchor}` : fileId,
      text,
      title: titles.at(-1),
      titles: titles.slice(0, -1),
    }
  }
}

const headingRegex = /<h(\d)[^>]*>(<a.*? href="#[^"]*"[^>]*>[\s\S]*?<\/a>)<\/h\1>/gi

const headingContentRegex = /<a.*? href="#([^"]*)"[^>]*><span>([\s\S]*?)<\/span><\/a>/i

const ignoreHeadingRegex = /<template[^>]*>[\s\S]*<\/template>/gi

function* splitPageIntoSections(html) {
  const result = html.split(headingRegex)
  result.shift()
  let parentTitles = []
  for (let i = 0; i < result.length; i += 3) {
    const level = Number.parseInt(result[i]) - 1
    const heading = result[i + 1]
    const headingResult = headingContentRegex.exec(heading)
    const title = clearHtmlTags(headingResult?.[2] ?? '').trim()
    const anchor = headingResult?.[1] ?? ''
    const content = result[i + 2]
    if (!title || !content) continue
    if (level === 0) parentTitles = [title]
    else {
      parentTitles.length = level
      parentTitles[level] = title
    }
    let titles = parentTitles.slice(0, level)
    titles[level] = title
    titles = titles.filter(Boolean)
    yield {
      anchor,
      titles,
      text: getSearchableText(content),
    }
  }
}

function getSearchableText(content) {
  content = clearHtmlTags(content)
  return content.length > MAX_SEARCHABLE_TEXT_LENGTH
    ? content.slice(0, MAX_SEARCHABLE_TEXT_LENGTH)
    : content
}

function clearHtmlTags(str) {
  str = str.replace(ignoreHeadingRegex, '')
  return sanitizeHTML(str, {
    allowedTags: [],
    allowedAttributes: {},
  })
}

function genHmrCode(m) {
  const func = `update${m[0].toUpperCase()}${m.slice(1)}`
  return `
if (import.meta.webpackHot) {
  import.meta.webpackHot.accept()
  if (__VUE_HMR_RUNTIME__.${m}) {
    __VUE_HMR_RUNTIME__.${func}(${m})
  }
}

if (import.meta.hot) {
  import.meta.hot.accept(({ ${m} }) => {
    __VUE_HMR_RUNTIME__.${func}(${m})
  })
}
`
}

