const __dirname = getDirname(import.meta.url)

function searchPlugin({locales = {}, isSearchable, ...searchOptions} = {}) {
  return (app) => ({
    name: '@vuepress-plume/plugin-search',
    clientConfigFile: path.resolve(__dirname, '../client/config.js'),
    define: {
      __SEARCH_LOCALES__: getFullLocaleConfig({
        app,
        name: '@vuepress-plume/plugin-search',
        default: SEARCH_LOCALES,
        config: locales,
      }),
      __SEARCH_OPTIONS__: searchOptions,
    },
    extendsBundlerOptions(bundlerOptions) {
      addViteOptimizeDepsInclude(bundlerOptions, app, [
        'mark.js/src/vanilla.js',
        '@vueuse/integrations/useFocusTrap',
        'minisearch',
      ])
    },
    onPrepared: async (app) => {
      if (app.env.isBuild)
        await prepareSearchIndex({
          app,
          isSearchable,
          searchOptions,
        })
      else {
        await prepareSearchIndexPlaceholder(app)
        prepareSearchIndexInBackground({
          app,
          isSearchable,
          searchOptions,
        })
      }
    },
    onPageUpdated: async (app, type, pageNew, pageOld) => {
      if (type === 'delete') {
        if (pageOld?.filePathRelative)
          await onSearchIndexRemoved(app, {
            page: pageOld,
            isSearchable,
            searchOptions,
          })
        return
      }
      const becameUnsearchable = !!isSearchable && !!pageNew && !isSearchable(pageNew)
      const page = becameUnsearchable ? pageOld : pageNew
      if (!page?.filePathRelative) return
      if (becameUnsearchable)
        await onSearchIndexRemoved(app, {
          page,
          isSearchable,
          searchOptions,
        })
      else
        await onSearchIndexUpdated(app, {
          page,
          isSearchable,
          searchOptions,
        })
    },
  })
}

export {prepareSearchIndex, searchPlugin}
